Definition VSCR : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!2'`8!1,4|:000;!2'bC'cH'cI").

Section LitLeaf.
Context {SCFG_P : ScfgP}.
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis LAY : PmLayout.pm0_layout L.
Variable NF : nat.
Variable E0 : env.
Variable M00 : mem.
Variable model0 : Model.
Variable LBo : list (Z * Z).
Variable sp0 : Z.
Variable d : CH.hdecl.
Variable W : list L5.range.
Variable BLS : list CA.blocks.
Variable GH : Type.
Variable gB : GH -> list (Z * Z).
Variable CredV : GH -> nat -> env -> credit -> Prop.
Variable XIv : GH -> nat -> env -> mem -> Prop.
Hypothesis STK : sp0 mod 16 = 0 /\ hl_ceil L + CH.hd_scr d <= sp0 /\ sp0 <= hl_sptop L /\ 0x7fff80000000 <= hl_sptop L <= 2 ^ 47.
Hypothesis SCR_pos : 0 <= CH.hd_scr d.
Hypothesis NF32 : (32 <= NF)%nat.
Hypothesis SP0 : bv_unsigned (ev E0 2) = sp0.
Hypothesis TP0 : ev E0 4 = Z_to_bv 64 (hl_tp L).
Hypothesis W_ok : forall r a, In r W -> L5.in_rng r a -> CH2.wclient L sp0 a.
Hypothesis CRS_ok : forall r, In r (CH.hd_crs d) -> SGP.region_vars_lt NF r = true /\ forall a, CH2.in_reg E0 r a -> CH2.sclient L LBo sp0 a.
Hypothesis WRS_ok : forall r, In r (CH.hd_wrs d) -> SGP.region_vars_lt NF r = true /\ forall a, CH2.in_reg E0 r a -> exists w, In w W /\ L5.in_rng w a.
Hypothesis IMG_ok : forall r a, In r (CH.hd_img d) -> fst r <= a < snd r -> hl_img_lo L <= a < hl_img_hi L /\ ~ hl_alloc_static L a /\ ~ in_errno L a.
Variable CPS : list CC.cutpoint.
Variable TAGS : list (list CC.tag).
Variable RETS : list (nat * nat * nat * Z).
Variable K : ShapeAlg.TSet.
Hypothesis K_nil : K [].
Hypothesis DEF0 : L5.defined M00 (sp0 - CH.hd_scr d) (CH.hd_scr d).
Hypothesis CredV_iE : forall g i j E E' cr, CredV g i E cr -> CredV g j E' cr.

Lemma lit_leaf_okU : forall (pc S Gd txt n : Z) i c k ps j cj ci (g : GH) M0c,
  literal_spec L pc S Gd txt n ->
  CH2V.okV L M00 LBo sp0 d W M0c ->
  CH2.is_leaf CPS TAGS i c k ps (CC.TOther pc) -> CH2.ret_of RETS i k = Some j -> nth_error CPS j = Some cj -> SR.ps_pc ps = pc ->
  CH2.custom_chk NF d LIT_SCR 0 (nth i BLS []) [(ELit 0, S, ELit 18)]
    (KRange (EVar (CC.cp_nx cj - APC.NCS + 5)) n n :: ESU2.lit_news S txt n) (Some (ELit txt)) c ps cj (nth i BLS []) = Some ci ->
  CH2.blocks_eqb (nth j BLS []) (nth i BLS []) = true ->
  Gd = S + 16 -> 0 <= S -> S + 18 <= 2 ^ 63 -> 0 <= txt < 2 ^ 64 -> 0 <= n < 2 ^ 64 ->
  StreamSim.wseg_ok RSEGS (Z_to_bv 64 S) 18 = true ->
  (forall a, S <= a < S + 18 -> exists w, In w W /\ L5.in_rng w a) ->
  (forall a, S <= a < S + 18 -> hl_img_lo L <= a < hl_img_hi L /\ ~ hl_alloc_static L a /\ ~ hl_alloc_ro L a) ->
  (forall E R (M : mem) model E' R' (M' : mem), CC.At (hl_segs L) c E R M ->
     CH2V.heap_ambV L HI NF E0 model0 LBo sp0 d W BLS GH gB CredV g M0c i E M model -> XIv g i E M ->
     env_agree (CC.cp_nx c) E E' -> CC.leaf_facts (hl_segs L) c ps E' R' M M' ->
     PML.lit_ok M' S Gd txt n /\ PML.img_ro M' /\
    (forall R2 (M2 : mem), CH2.ci_csp ci <= 0 -> - CH.hd_scr d <= CH2.ci_csp ci - LIT_SCR ->
       lit_done M2 S Gd txt n -> L5.frame_but ((sp0 + CH2.ci_csp ci - LIT_SCR, LIT_SCR) :: [(S, 18)]) M' M2 -> mem_grows M' M2 ->
        XIv g j (CH2.retEx E' (CH2.ci_nx ci) [] R2) M2)) ->
  CH2V.leaf_okV L HI NF E0 M00 model0 LBo sp0 d W BLS GH gB CredV XIv CPS K PML.fp_ok g M0c i c ps.
Proof.
  intros pc S Gd txt n i c k ps j cj ci g M0c LIT HOKV IL Hret Hcj Hpc Hchk B3 HG HS0 HS1 HT HN WS SW SCL CALL.
  apply (EPU.pure_leaf_okV L HI HIok LAY NF E0 M00 model0 LBo sp0 d W BLS GH gB CredV XIv STK SCR_pos NF32 SP0 TP0 W_ok CRS_ok WRS_ok IMG_ok
           CPS TAGS RETS K DEF0 CredV_iE pc LIT_SCR _ _ _ i c k ps j cj ci g M0c HOKV IL Hret Hcj Hpc Hchk B3).
  intros E R M model E' R' M' cr fx' HAt HAmb HXI Hag HLF CF HH HC HFP Hk.
  destruct (CALL E R M model E' R' M' HAt HAmb HXI Hag HLF) as (HLOK & HIMG & HXRET).
  pose proof CF as [HA' HR Hreq (V1 & V2 & V3 & V4 & V5) HK [Hra Hraok] (Hsp & Hc1 & Hs0 & Hc2) Hstk Htp HagE' Hden Hmeas].
  destruct HA' as (Hmo & _). destruct Hmo as (Hhalt & Hlazy & _).
  apply (LIT (sp0 + CH2.ci_csp ci) (CC.cp_pc cj) fx' R' M' model K Hhalt Hlazy K_nil HFP).
  - split; [split; [exact Hra | split; [exact Hraok | split; [exact Hsp | split; [rewrite Htp, (PmLayout.ly_tp L LAY); reflexivity | exact Hstk]]]]|].
    split; [exact HLOK|]. split; [|exact HIMG].
    exact (SP.writable_static RSEGS M' S 18%nat WS ltac:(lia) ltac:(lia)).
  - intros fx2 R2 M2 HFP2 (Pa0 & Pa1 & Pdone) HRP HFB HGR.
    set (E2 := CH2.retEx E' (CH2.ci_nx ci) [] R2).
    apply (Hk fx2 R2 M2 [(S, 18)] HFP2).
    + intros r Hr0 Hcs. exact (CH2.regs_preserved_kept R' R2 HRP r Hr0 Hcs).
    + cbn [edenot]. exact Pa0.
    + exact HFB.
    + exact HGR.
    + intros w a [<-|[]] Hin. unfold L5.in_rng in Hin. cbn [fst snd] in Hin. split.
      * exists (ELit 0, S, ELit 18). split; [left; reflexivity|].
        unfold CH2.in_reg, estart, elenZ. cbn [a_base a_off edenot]. rewrite !u64_of_Z by lia. lia.
      * unfold EPU.wfree. right. split; [lia|]. split.
        -- intros LB [(P1 & P2 & P3)|P]; destruct (SCL a Hin) as (X1 & X2 & X3); [apply P3; split; assumption | exact (X3 P)].
        -- intros (K1 & K2 & K3 & K4). destruct (SW a Hin) as (w' & Hw' & Hin2). exact (K4 w' Hw' Hin2).
    + intros X HX _. destruct HX as [<-|HX].
      * cbn [kentry_ok]. replace (CC.cp_nx cj - APC.NCS + 5)%nat with (CH2.ci_nx ci + 5)%nat by (rewrite V5; lia).
        cbn [edenot]. unfold E2. rewrite retEx0_a1. unfold PML.a1 in Pa1. rewrite Pa1. rewrite u64_of_Z by lia. lia.
      * subst Gd. destruct Pdone as (D1 & D2 & D3 & D4). rewrite (PmLayout.ly_segs L LAY).
        cbn [ESU2.lit_news In] in HX. destruct HX as [<-|[<-|[<-|[<-|[]]]]].
        -- eapply PB2.kword8_intro with (A := S + 16) (z := 1); [unfold estart; cbn [a_base a_off edenot]; rewrite (u64_of_Z 0) by lia; lia | lia | lia | reflexivity | lia | exact D1].
        -- eapply PB2.kword8_intro with (A := S + 17) (z := 1); [unfold estart; cbn [a_base a_off edenot]; rewrite (u64_of_Z 0) by lia; lia | lia | lia | reflexivity | lia | replace (S + 17) with (S + 16 + 1) by lia; exact D2].
        -- eapply CL5.kword64_intro with (A := S) (z := txt); [unfold estart; cbn [a_base a_off edenot]; rewrite (u64_of_Z 0) by lia; lia | lia | lia | reflexivity | exact D3].
        -- eapply CL5.kword64_intro with (A := S + 8) (z := n); [unfold estart; cbn [a_base a_off edenot]; rewrite (u64_of_Z 0) by lia; lia | lia | lia | reflexivity | exact D4].
    + exact (HXRET R2 M2 Hc1 Hc2 Pdone HFB HGR).
Qed.
End LitLeaf.

Lemma lit_ok_agree : forall (M M' : mem) S Gd txt n, Gd = S + 16 -> 0 <= S -> S + 18 <= 2 ^ 64 ->
  L5C.agree_on M M' S 18 -> PML.lit_ok M S Gd txt n -> PML.lit_ok M' S Gd txt n.
Proof.
  intros M M' S Gd txt n -> HS0 HS1 AG [(A1 & A2 & A3 & A4)|(A1 & A2 & A3 & A4)]; [left|right];
    (split; [apply (EK.u8_agree M M'); [eapply L5C.agree_on_sub; [exact AG | lia | lia] | lia | lia | exact A1]|]);
    (split; [apply (EK.u8_agree M M'); [eapply L5C.agree_on_sub; [exact AG | lia | lia] | lia | lia | exact A2]|]);
    (split; [apply (EK.u64_agree M M'); [eapply L5C.agree_on_sub; [exact AG | lia | lia] | lia | lia | exact A3]|]);
    (apply (EK.u64_agree M M'); [eapply L5C.agree_on_sub; [exact AG | lia | lia] | lia | lia | exact A4]).
Qed.

End EVNHU.
